INSERT INTO joint_inspections (id, inspection_date, site_name, subcontractor, check_items, photos, created_by, created_at, headquarters) VALUES (7, '2026-06-26', '앞산터널 - 대구광역시 달서구 도원동 1396-362(T/RX 예방점검)', '와이어블', '[{"item":"장비 설치 상태","issue":"양호","improvement":"-"},{"item":"위험요소 내재 상태","issue":"케이블 작업 시 이동식 사다리 작업 간 전도 위험","improvement":"이동식 사다리 안전수칙 준수 및 2인1조 시행"},{"item":"화재 시 위험방지 상태","issue":"분진으로 인한 화재 위험","improvement":"장비 및 분전함 내/외부 주기적 분진 청소 실시"},{"item":"전기관련 작업 시 안전 상태","issue":"분진으로 인한 전기화재 위험","improvement":"장비 및 분전함 내/외부 주기적 분진 청소 실시"},{"item":"안전보건 표지판 상태(필요 시)","issue":"양호","improvement":"-"},{"item":"적정 작업인력 배치 및 작업자 보호구의 착용 상태","issue":"양호","improvement":"-"},{"item":"작업장 환경 상태","issue":"터널 진입 시 진입발판 파손으로 빠짐 및 전도 사고 주의 필요 ","improvement":"안전표지 부착 및 진입 시 전방 주시 "},{"item":"기타","issue":"양호","improvement":"-"}]', '[{"url":"/objects/uploads/joint_1782458230776.jpg","name":"20260626_140557.jpg"},{"url":"/objects/uploads/joint_1782458230626.jpg","name":"20260626_141854.jpg"}]', '10001284', '2026-06-09T00:42:45.574646', '대구본부');
